        public void TestException()
        {

            try
            {
                Exception newException = new Exception("This is an exception generated by this service.");
                newException.Source = "MAXIMUS.Services.PDMS.PDMSService";
                throw newException;
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

