        public bool CheckProviderRevalidated(int regId)
        {
            try
            {
                DataSet result = ProviderController.CheckProviderRevalidated(regId);

                if (result?.Tables["RevalidationStatus"]?.Rows?.Count > 0)
                {
                    return Convert.ToBoolean(result.Tables["RevalidationStatus"].Rows[0]["IsRevalidationDateRequired"]);
                }

                // Default to required if no data found (safer approach)
                return true;
            }
            catch (Exception ex)
            {
                throw CoreException.ThrowException(ex);
            }
        }

