        private void ProcessOverride(int errorId, int partyId, int medicaidPK, int resolvingReasonTypeId, string userId)
        {
            // Given the resolvingReasonTypeId:
            //  1       = Reviewed/Approved or Duplicate Provider
            //  Default = All others
            switch (ProviderController.GetOverrideReasonTypeId(resolvingReasonTypeId))
            {
                case 1:
                    ProviderController.UpdatePDMSStatus(true, errorId, medicaidPK, partyId, Constants.PDMSStatusType.Processed, DateTime.Now, userId);
                    ProviderController.UpdatePDMSStatus(errorId, partyId, Constants.PDMSStatusType.Processed, DateTime.Now, userId);
                    break;
                default:
                    // Update Service Location status
                    ProviderController.UpdatePDMSStatus(true, errorId, medicaidPK, partyId, Constants.PDMSStatusType.PendingMMISSubmission, DateTime.Now, userId);
                    // Update Provider status
                    ProviderController.UpdatePDMSStatus(errorId, partyId, Constants.PDMSStatusType.PendingMMISSubmission, DateTime.Now, userId);
                    break;
            }
        }

        // Only for Update Record
        private void UpdatePDMS(int errorId, int partyId, int resolvingActionTypeId, int medicaidPK, int opt, string newValue, string userId)
        {
            try
            {
                if (resolvingActionTypeId == Constants.ResolvingActionType.UpdateRecord)
                {
                    switch (opt)
                    {
                        case 1:
                            ProviderController.UpdateLicense(partyId, medicaidPK, newValue, userId);
                            break;
                        case 2:
                            ProviderController.UpdateDEA(partyId, medicaidPK, newValue, userId);
                            break;
                        case 3:
                            ProviderController.UpdateUPIN(partyId, medicaidPK, newValue, userId);
                            break;
                        case 4:
                            ProviderController.UpdateSpecialty(partyId, medicaidPK, Convert.ToInt32(newValue), DateTime.Now, userId);
                            break;
                    }
                    // Update Service Location and Provider status
                    ProviderController.UpdatePDMSStatus(true, errorId, medicaidPK, partyId, Constants.PDMSStatusType.PendingMMISSubmission, DateTime.Now, userId);
                    ProviderController.UpdatePDMSStatus(errorId, partyId, Constants.PDMSStatusType.PendingMMISSubmission, DateTime.Now, userId);
                }
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

        private void UpdatePDMS(int errorId, int partyId, int resolvingActionTypeId, int resolvingReasonTypeId, string terminateEnrollment,
            int medicaidPK, string userId)
        {
            try
            {
                if (resolvingActionTypeId == Constants.ResolvingActionType.Rejection)
                {
                    ProviderController.UpdatePDMSStatusAll(partyId, Constants.PDMSStatusType.PendingCAQHDelete, DateTime.Now, userId);
                    ProviderController.UpdateCAQHStatus(partyId, Constants.CAQHStatusType.RemovedFromRoster, Constants.RosterStatusType.Inactive,
                        DateTime.Now, userId);
                }
                else if (resolvingActionTypeId == Constants.ResolvingActionType.Termination)
                {
                    ProviderController.UpdatePDMSStatusAll(partyId, Constants.PDMSStatusType.Terminated, DateTime.Now, userId);
                    ProviderController.UpdateCAQHStatus(partyId, Constants.CAQHStatusType.RemovedFromRoster, Constants.RosterStatusType.Inactive,
                        DateTime.Now, userId);
                    ProviderController.MMISTerminate(partyId, terminateEnrollment);
                    ProviderController.TerminateAllServiceLocations(partyId, DateTime.Now, userId);
                }
                else if (resolvingActionTypeId == Constants.ResolvingActionType.Override)
                {
                    ProcessOverride(errorId, partyId, medicaidPK, resolvingReasonTypeId, userId);
                }
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

