        public void EmailNotify(int errorId, int toPartyId, string toEmail, int resolvingActionTypeId, int resolvingReasonTypeId,
            string terminateEnrollment, DateTime eventDate, string providerName, string npi, string userId, int regId)
        {
            try
            {
                // Send the email
                int communicationEventId = 0;
                //int adminPartyId = ProviderController.GetAdminPartyId();
                // if testing enabled
                string testing = AppSettings.Get("TestEmailEnabled", bool.TrueString.ToLower());
                if (testing.ToLower() == bool.TrueString.ToLower())
                {
                    toEmail = AppSettings.Get("TestEmailAddress", "jfetters@policy-studies.com");
                }
                ProviderController.EmailNotification(AppSettings.Get("PDMS_SVC_TemplatesPath", string.Empty), AppSettings.Get("SmtpFromEmailAddress", string.Empty), toEmail, resolvingActionTypeId, resolvingReasonTypeId,
                    eventDate, providerName, npi, DateTime.Now, userId, ref communicationEventId, regId);
                // Mark error status Closed or Pending
                int errorStatusId = Constants.ErrorStatusType.Closed;
                if (resolvingActionTypeId == Constants.ResolvingActionType.AdditionalInfo ||
                    resolvingActionTypeId == Constants.ResolvingActionType.Warning)
                    errorStatusId = Constants.ErrorStatusType.Pending;
                UpdateError(errorId, errorStatusId, communicationEventId, resolvingActionTypeId, resolvingReasonTypeId, userId);
                UpdatePDMS(errorId, toPartyId, resolvingActionTypeId, resolvingReasonTypeId, terminateEnrollment, 0, userId);
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

        // For processing SubmitRoster errors, Update the PDMS Status, we do not have a PartyId
        public void OverrideErrorSubmitRoster(int errorId, int submitRosterId, int resolvingActionTypeId, int resolvingReasonTypeId, string userId)
        {
            try
            {
                // Mark error status Closed
                UpdateError(errorId, Constants.ErrorStatusType.Closed, null, resolvingActionTypeId, resolvingReasonTypeId, userId);
                // Set the PDMS status
                ProviderController.UpdatePDMSStatusSubmitRoster(submitRosterId, Constants.PDMSStatusType.PendingCAQHSubmission,
                    DateTime.Now, userId);
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

