        /// <param name="threadId">The GUID of the currently running thread</param>
        /// <param name="logProcessName">The name of the method being called</param>
        /// <param name="logMessage">The message to write to the log (max: 1500)</param>
        public void CreateLogEntry(Guid threadId, string logProcessName, string logMessage)
        {
            try
            {
                Logging log = new Logging(threadId, logProcessName);
                log.CreateLogEntry(logMessage);
            }
