        public DataSet GetFilteredUsers(string username, string contactname, string orgName, string taxId, string NPI, string role, int pageSize, int startIndex)
        {
            try
            {
                List<SqlParameter> parameters = new List<SqlParameter>();

                if (!string.IsNullOrEmpty(username))
                    parameters.Add(SqlParms.CreateParameter("username", DbType.String, username, false));

                if (!string.IsNullOrEmpty(contactname))
                    parameters.Add(SqlParms.CreateParameter("contactname", DbType.String, contactname, false));

                if (!string.IsNullOrEmpty(orgName))
                    parameters.Add(SqlParms.CreateParameter("orgname", DbType.String, orgName, false));

                if (!string.IsNullOrEmpty(taxId))
                    parameters.Add(SqlParms.CreateParameter("taxId", DbType.String, taxId, false));

                if (!string.IsNullOrEmpty(NPI))
                    parameters.Add(SqlParms.CreateParameter("NPI", DbType.String, NPI, false));

                if (!string.IsNullOrEmpty(role))
                    parameters.Add(SqlParms.CreateParameter("role", DbType.String, role, false));

                parameters.Add(SqlParms.CreateParameter("pageSize", DbType.Int32, pageSize, false));
                parameters.Add(SqlParms.CreateParameter("startIndex", DbType.Int32, startIndex, false));

                DataSet ds = new DataSet();
                ds = DataAccess.ExecuteStoredProcedure("usp_GetFilteredUsers", parameters, "FilteredUsers");
                ds.Tables[0].TableName = "FilteredUsers";
                return ds;
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

