        public void NotifyProviderOfDIDDReferral(string firstName, string lastName, string groupIdentityName, string appNumber, DateTime? contractFromDate, DateTime? contractToDate, string email, string inputSubject)
        {
            try
            {
                if (string.IsNullOrEmpty(firstName) && string.IsNullOrEmpty(lastName)) firstName = groupIdentityName;
                string emailFrom = AppSettings.Get("SmtpFromEmailAddress", string.Empty);
                string templatePath = AppSettings.Get("PDMS_SVC_TemplatesPath", string.Empty);
                UserController.NotifyProviderOfDIDDReferral(templatePath, email, firstName, lastName, appNumber, contractFromDate, contractToDate, emailFrom, inputSubject);
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

