        public bool ValidateNPIUniqueness(int regId, string npi, bool isNursingFacility)
        {
            try
            {
                List<SqlParameter> parameters = new List<SqlParameter>();

                parameters.Add(SqlParms.CreateParameter("NPI", DbType.String, npi, false));
                parameters.Add(SqlParms.CreateParameter("REG_ID", DbType.Int32, regId, false));

                int activeProviderCount = Convert.ToInt32(DataAccess.ExecuteScalar("usp_ValidateNPIUniqueness", parameters));

                if (activeProviderCount == 0)
                {
                    return true;
                }
                //else if (isNursingFacility && activeProviderCount == 1) //OHPNM-9679 For Nursing facility build & wings entries will generate on registration with same NPI and different REGIDs.
                //{
                //    return true;
                //}
                else
                {
                    return false;
                }
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

        public int InsertTaxonomyCode(int specialtyTypeID, int providerTypeID, string taxonomyCode, string taxonomyDetail, DateTime expirationdate, string mmis_specialty_type_id, DateTime lastModifiedDate, Guid lastModifieduserID)
        {
            try
            {
                List<SqlParameter> parameters = new List<SqlParameter>();

                parameters.Add(SqlParms.CreateParameter("SPECIALTY_TYPE_ID", DbType.Int32, specialtyTypeID, false));

                parameters.Add(SqlParms.CreateParameter("PROVIDER_TYPE_ID", DbType.Int32, providerTypeID, false));

                if (!string.IsNullOrEmpty(taxonomyCode))
                    parameters.Add(SqlParms.CreateParameter("TAXONOMY_CODE", DbType.String, taxonomyCode, false));

                if (!string.IsNullOrEmpty(taxonomyDetail))
                    parameters.Add(SqlParms.CreateParameter("TAXONOMY_NAME", DbType.String, taxonomyDetail, false));

                parameters.Add(SqlParms.CreateParameter("MMIS_SPECIALTY_TYPE_ID", DbType.String, mmis_specialty_type_id, false));
                parameters.Add(SqlParms.CreateParameter("EXPIRATION_DATE", DbType.DateTime, expirationdate, false));
                parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_DATE_TIME", DbType.DateTime, lastModifiedDate, false));
                parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_USER", DbType.Guid, lastModifieduserID, false));

                int taxonomyID = Convert.ToInt32(DataAccess.ExecuteScalar("insertTAXONOMY_TYPE", parameters));

                return taxonomyID;
            }
            catch (Exception ex)
            {
                throw new FaultException<ServiceException>(new ServiceException(CoreException.ThrowException(ex)), ex.Message);
            }
        }

